template<class T>
class singleton_ptr
{
    T *pointer;

public:
    operator T *() const
    {
        return pointer;
    }
};

class singleton
{
public:
    virtual ~singleton();
};

class os_developer_options : public singleton
{
    int flags[80];
    static singleton_ptr<os_developer_options> instance;

public:
    enum flags_t
    {
        FLAG_NO_AUDIO = 17
    };

    static os_developer_options *inst()
    {
        return instance;
    }

    bool is_flagged(flags_t flag) const
    {
        return flags[flag] != 0;
    }
};

class PauseMenuSystem;
class FEMenuEntry;
class color32
{
    unsigned int value;
};

enum
{
    SONGS_PER_SCREEN = 6
};

class PlaylistMenuClass : public FEMenu
{
private:
    PauseMenuSystem *sys;
    stringx *song_names;
    FEMenuEntry *songName[SONGS_PER_SCREEN];
    TextString *upArrow;
    TextString *downArrow;
    TextString *helpText2;
    TextString *lineNumbers[SONGS_PER_SCREEN];
    TextString *onOff[SONGS_PER_SCREEN];
    TextString *playing;
    TextString *currentSong;
    TextString *currentArtist;
    int offset;
    int pos;
    int active;
    int numSongs;
    color32 col;
    color32 colh;
    bool tweaked;

public:
    ~PlaylistMenuClass();
};

PlaylistMenuClass::~PlaylistMenuClass()
{
	if (upArrow)
		delete upArrow;
	if (downArrow)
		delete downArrow;
	if (helpText2)
		delete helpText2;

	if (playing)
		delete playing;
	if (currentSong)
		delete currentSong;
	if (currentArtist)
		delete currentArtist;

	for (int i=0; i < SONGS_PER_SCREEN; i++)
	{
		if (lineNumbers[i])
			delete lineNumbers[i];
		if (onOff[i])
			delete onOff[i];
	}

	if (!os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_AUDIO))
		delete[] song_names;
}

